-- ISSUE-NOTES-E-1 (2026-11-05, charter pillar autonomy; cluster E-metrics-portfolio of the open-issue sweep; OWNER-NO-LOOSE-ENDS-1).
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261105_e_issue_notes
-- Rollback: UPDATE agent_issues SET description = (SELECT b.description FROM bak_20261105_e_issue_notes b WHERE b.id = agent_issues.id) WHERE id IN (SELECT id FROM bak_20261105_e_issue_notes)
-- CAUSE-MAPPED: no metric is registered here; this appends a dated finding to the description of fourteen open issues whose metric cannot be moved by one code change today.
-- Each note states what was read on 2026-11-05, which loop owns the lever and what closes the issue, so the next session starts from the evidence and no breach stays a bare number.
-- The notes avoid the planner lines (no task or anchor line): nothing here hands a doer a second copy of work another issue already owns.

CREATE TABLE IF NOT EXISTS bak_20261105_e_issue_notes AS SELECT id, description FROM agent_issues WHERE id IN (1000548, 1000856, 1000702, 1000671, 1001349, 1001530, 1000978, 1001004, 1000792, 1000915, 1000598, 1000618, 1000684, 1000741);

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (ask_answers_7d, GitHub 5199): ask_events by day from 2026-10-20: 3 to 5 events a day on ordinary days (the fleet journey probe asks one synthetic question every JRN_ASK_EVERY_H = 6 hours, about 4 a day) and bursts of 27 and 33 on 2026-10-25 and 26 and 15 on 2026-11-02; errors 4 (2026-10-26 only), limited 0. So 58 on 2026-10-21 to 12 on 2026-11-05 is a burst ageing out of the 7-day window over a floor made of the fleet''s own probe; no serving defect found. Real reader demand is well under the target of 70 a week. Lever: readers (READER-YIELD-1, engaged external sessions), owner QNFO.REACH; the concept navigator on ask.qwav.org (qnfo-ai-search 2.15.0, 2026-11-05) is the newest change. Closes through its own contract (the 7-day trend stops declining) or a reader gain; a measurement that excluded the journey probe would read lower still and is not a fix.'
WHERE id = 1000548 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (backlog_age_p95_min, GitHub 5488): the metric is the 95th percentile age of open agent_issues; it read 25,300 minutes (17.6 days) at 01:33Z, up from 14,461 on 2026-10-23, rising about 800 a day because the oldest 5 percent of the stock sit open while new ones are filed. The target (60 minutes, one tick) is reachable only when the old stock is drained, so no single code change moves it: the lever is the remediation sweep of 2026-11-04 and 05 (nine clusters over the 295 open GitHub mirrors) and the ISSUE-SLA-2H-1 drain. Owner qnfo-fleet-control (QNFO.OPS); it closes through its contract when the 7-day mean stops rising.'
WHERE id = 1000856 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (ci_gate_bypass_count, GitHub 5729): the measurement defect is already fixed on main by CI-GATE-ERA-1 and CI-GATE-ERA-2 (scripts/bp26_cfapi.py): the audit judged 30 days of merges against one list of required checks and counted as bypasses 15 rows for the advisory deploy-gate, 3 for it red and 10 for a reusable-workflow check name (the code comment says 38 artifacts; its own breakdown sums to 28). What remains, about 25, are real merges that skipped a check: 15 with no guard check at all (the bulk merges of 2026-11-01 and 2026-11-03), 8 with a red guard and 2 with a red scans on 2026-11-04 21:15Z (sessions merged by hand 20 seconds after the failure). They leave the 30-day window by 2026-12-04 at the latest; prevention is the required checks versions and scans of the main ruleset, which a manual merge by a bypass actor still overrides. Owner QNFO.OPS; closes when trigger 14530 clears.'
WHERE id = 1000702 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (forecast_resolution_criteria_complete, GitHub 5714): q08-signal.q08_forecasts holds 3 open forecasts and none passes the proxy in scripts/bp26_forecast.py: all three name a date (on or before 2026-12-31 / 2027-07-31), two name a source (a release, a press release) and one does not, and none carries an edge-case clause (the EDGE pattern: if, unless, otherwise, void, ambiguous, not published, in the event, fails to ...). So the writer states the date and the source and never says what happens when the source does not publish. The published fields of an open forecast are immutable (BP26-FORECAST-HYGIENE), so the fix is the generator, not a back-fill: the resolution-criteria gate of RM-FORECAST-HYGIENE-1 (GitHub 5576, roadmap 1697, q08-signal-engine) must require the edge-case clause before a forecast is stored. Owner QNFO.RSCH; the share rises as compliant forecasts are added and the metric reads 1 at the latest when the three open ones resolve (two by 2026-12-31, the third by 2027-07-31). Read by running the proxy of scripts/bp26_forecast.py on the three texts: the PJM forecast matches the date pattern only, the Broadcom and TrendForce forecasts match source and date but not the edge case.'
WHERE id = 1000671 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (q08 publishing stall, GitHub 6469 and 6859): the newest published piece in q08-signal.published_pieces is 2026-11-02T09:04Z, 65 hours before this read. engine_runs of the last 24 hours holds only 6 ended runs: 3 deferred (forecast research found 3, 3 and 4 usable sources, 6 needed) and 3 gate_failed (accuracy: unsupported claim; accuracy: year and name not in the source; ensemble: the edited draft was still not worth reading), so the stall is two things at once: few attempts (Q08-TICK-ALLOWANCE-1, q08-signal-engine 0.43.0, decides on its own whether a tick starts an attempt, a cost lever) and gates that reject most drafts for reasons that are the gates working (unsupported figures, a panel that finds the piece not worth reading). OUTPUT-QUALITY-LEDGER-1 forbids lowering a gate to publish more; the lever is the gate economics and the source supply, owned by roadmap row 1752 (EK-5, GitHub 5613, q08-signal-engine). Closes when a run publishes; the q08_hours_since_last_piece trend (7d mean 33 hours, target under 8) follows.'
WHERE id IN (1001349, 1001530) AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (improvement_rate_7d, GitHub 6155): the lever review above proposes lowering the registry target from 0.5 to 0.3. That does not clear the breach: the trigger fires on the value (0.2419 below 0.3), not on the target text, so a lower target only hides the gap. The measure itself (improvementEvaluate in qnfo-fleet-control) counts a metric as improved when it moved 5 percent in its good direction with 4 daily points in each 7-day window, and counts every other evaluable metric as flat or regressed. Read from metric_history 2026-11-05: 271 metrics evaluable, 64 with identical means in both windows (43 of them exactly 0, a defect count that is at its ideal and cannot improve), 38 moving under 5 percent. Excluding the metrics that sit at their ideal in both windows would lift the rate from 0.24 to roughly 0.29 on these counts, still under 0.3, so the breach is mostly real: fewer than a quarter of the fleet''s measures improved this week. Lever: the regressed and flat off-target metrics in order of pillar weight (the METRIC-REGRESSION-1 and METRIC-TRIGGER issues of this sweep); a denominator that leaves out held-at-ideal metrics is a measure change for the improvement loop owner, to be argued on its own evidence.'
WHERE id = 1000978 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (plus_shipped_7d, GitHub 6179): plus_shipped_7d is the minimum over the 8 active plusable products (product_registry, qnfo-ops excluded) of verified pluses in plus_outcome_checks in 7 days, so it stays 0 until every product has one. Cause of the zero: the plus step of management-personas-plus failed on every hourly run with a CHECK constraint on plus_ledger.status (fleet_runs 69871 to 70221, last 2026-11-04T23:50Z); PR 7345 (PLUS-LEDGER-STATUS-1) widened the constraint after that run. plus_ledger holds 2 proposed rows (companion-today onboarding card, jobs stretch grouping). With a daily cap on pluses across the fleet (3 when designed) and 8 products, the earliest recovery is a few days after the code loop ships them, so the breach is real and time-bound. Owner qnfo-fleet-control; closes when the metric recovers; GitHub 5759 (the companion-today plus) is the first item.'
WHERE id = 1001004 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (PLUS-1 onboarding card, GitHub 5759): not shipped in this sweep because both files the change touches were held by other work claims when tried (2026-11-05 00:10Z to 01:45Z): personal-api/companion.js (the page source, inbox() renders the Recently captured list; held by a code task of the loop) and personal-api/worker.js (the generated inline copy, held by code task ct_im1001641 until 03:18Z). The change is small and specified above: when /companion/api/inbox returns no items, render one card in #inbox that says what the companion logs and one line each for Capture, Talk, Do, Learn and Journal, and drop it once the first capture lands; edit companion.js, run node personal-api/inline-companion.mjs, bump personal-api, add a case to the companion suites and the phone journey. The parked code task ct_im1000792 is the doer; the closing probe (plus_ledger row for companion-today shipped or kept) is unchanged.'
WHERE id = 1000792 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (voice-stt compat date, GitHub 5794): voice-stt is a live script with no repository directory (worker_compat_state: live 2026-10-01, toml_date NULL, "wrangler.toml declares no compatibility_date"). Read through the account API: bindings AI, VAULT (R2 obsidian-vault), NOTE_PREFIX (plain text Daily/), AUTH_TOKEN (secret); the code is a 3.3 KB Whisper v3 turbo endpoint that appends the transcript to the daily note in the vault. Two ways to advance its date: adopt the source (voice-stt/ with wrangler.toml, charter-pillar personal, probes.json, a mirror) so the canonical deploy applies the reviewed date as for the other three workers of this wave, or change the setting through an allowlisted cf_ops_actions step. The first is blocked by the net-zero rule (workers_standards_guard worker-budget-net-zero: a new tracked Worker at or over the cap of 30 needs a same-change RETIRED or FOLDED marker for an existing one) and the second is a write to a live worker setting that needs a scratch-script test of the partial-PATCH semantics first. Newest COMPAT_FLIPS entry is 2026-10-01 (not met by this worker), so the exposure is nil today; the age (34 days) is the only gap. Owner QNFO.INFRA; closing probe is the worker_compat_state row once the date advances.'
WHERE id = 1000915 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (NET-ZERO-1, GitHub 5684): fleet_worker_census read 2026-11-04T13:05Z: qnfo-ipatent 1,043 events in 24 hours (and 14 bindings elsewhere by the fleet-graph impact read of 2026-10-28: the dashboard tile, the ops ipatent database alias), qnfo-youtube-shorts 782 events. The retirement named in the issue is a live public product with its own D1 and 28 dependents in the fleet graph, so it is not the idle worker the standing grant covers; the three steps of the earlier analysis (drop the dashboard binding and tile, move public_data ipatent_activity and the ipatent alias out of qnfo-ops, RETIRED marker and delete-worker after a D1 backup) stand and each needs the dependent to be changed first. The probe (qnfo-ipatent retired and qnfo-youtube-shorts live) is a proxy for the charter rule, which is about the worker count: 37 live workers in service_registry on 2026-11-05 (kind worker, state live) against a cap of 30. A retirement of a worker with no dependents and no traffic satisfies the rule equally; the candidate list belongs to WORKER-COUNT-1 (roadmap rows filed 2026-11-04 by PR 7393). Owner QNFO.INFRA.'
WHERE id = 1000598 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (slo_attainment_28d_min, GitHub 5686): slo_attainment_28d_min is the minimum over the registered SLOs of the 28-day attainment; it read 0.479 on 2026-11-05 (0.7083 when filed), so the worst SLO met its objective for under half of the last 28 days. A 28-day minimum recovers gradually and only as the bad days leave the window: once the failing SLO is healthy it gains about 1/28 a day, so it cannot reach 0.995 until 28 days after its last bad day (2026-12-03 if that was today). Which SLO that is and why it fails was not read in this sweep; a postmortem for each breaching SLO (postmortem_coverage, GitHub 5719) is the practice the BP26 predicate asks for. Owner QNFO.OPS.'
WHERE id = 1000618 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (postmortem_coverage, GitHub 5719): 0.9556 on 2026-11-05, so some incidents lack a postmortem record (the count was not read in this sweep); the same BP26-SLO-ERROR-BUDGETS predicate as slo_attainment_28d_min (GitHub 5686). The gap is closed by writing the missing postmortems from their incident evidence, not by editing the denominator. Owner QNFO.OPS.'
WHERE id = 1000684 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05 (program_focus_without_doer, GitHub 5740): has_doer in v_program_focus_candidates is true when the description holds a task line for the code loop, linked_session is set, or an active remediation contract exists; a metric-breach issue whose only contract is in status monitoring (it watches the metric and closes on recovery) therefore reads as having no doer, and the managers keep picking such issues because they are the highest risk. 15 at 2026-11-04T22:30Z against a threshold of 5 (12 listed at 2026-11-05 01:00Z: INFRA 3, OPS 5, REACH 4, all METRIC-TRIGGER or ROADMAP-1 issues). A doer for such an issue is the lever in its trigger text, written as a task line with an anchor so the code loop opens the pull request. Owner qnfo-fleet-control (management-personas).'
WHERE id = 1000741 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05') = 0;
